import 'dart:convert';
import 'package:flutter/material.dart';

// Exact artwork from the approved PAYDAY preview, kept intact.
class PaydayBrand extends StatelessWidget {
 const PaydayBrand({super.key, this.compact = false});
 final bool compact;
 static final light = MemoryImage(base64Decode(_light));
 static final dark = MemoryImage(base64Decode(_dark));
 @override Widget build(BuildContext context) => Semantics(
  label: 'PAYDAY. Every dirham, in control.', image: true,
  child: ExcludeSemantics(child: Image(
   image: Theme.of(context).brightness == Brightness.dark ? dark : light,
   width: compact ? 190 : 214, height: compact ? 59 : 66,
   fit: BoxFit.contain, filterQuality: FilterQuality.high)));
}
const _light = '';
const _dark = '';

const paydayIconBase64 = '';
